 52  @Composable
 53  fun ShelfTapApp(repository: CatalogueRepository) {
 54      val vm: ShelfTapViewModel = viewModel(factory = ShelfTapViewModel.Factory(repository))
 55      val selected by vm.selectedId.collectAsStateWithLifecycle()
 56      MaterialTheme {
 57          Surface(modifier = Modifier.fillMaxSize()) {
 58              if (selected == null) CatalogueScreen(vm) else DetailScreen(vm, selected!!)
 59          }
 60      }
 61  }
