 63  @OptIn(ExperimentalMaterial3Api::class)
 64  @Composable
 65  private fun CatalogueScreen(vm: ShelfTapViewModel) {
 66      val items = vm.titles.collectAsLazyPagingItems()
 67      val query by vm.queryFlow.collectAsStateWithLifecycle()
 68      Scaffold(topBar = { TopAppBar(title = { Text("ShelfTap catalogue") }, colors = TopAppBarDefaults.topAppBarColors()) }) { padding ->
 69          Column(Modifier.padding(padding).fillMaxSize()) {
 70              OutlinedTextField(value = query, onValueChange = vm::setQuery, label = { Text(stringResource(R.string.search_catalogue)) }, singleLine = true, modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp))
 71              if (items.itemCount == 0 && items.loadState.refresh is androidx.paging.LoadState.NotLoading && query.isNotBlank()) {
 72                  Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) { Text(stringResource(R.string.no_books_found)) }
 73              } else {
 74                  LazyColumn(contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
 75                      items(items.itemCount, key = { items[it]?.id ?: "placeholder-$it" }, contentType = { "title" }) { index ->
 76                          items[index]?.let { title ->
 77                              TitleRow(title, Modifier.fillMaxWidth()) { vm.open(title.id) }
 78                              if (index >= items.itemCount - 5) vm.loadNextPage()
 79                          }
 80                      }
 81                  }
 82              }
 83          }
 84      }
 85  }
