11      fun page(query: String = "", page: Int, size: Int = 50): Page {
12          val encoded = java.net.URLEncoder.encode(query, "UTF-8")
13>         val connection = (URL("$base/api/titles?q=$encoded&page=$page&size=$size").openConnection() as HttpURLConnection).apply {
14              requestMethod = "GET"; connectTimeout = 10_000; readTimeout = 20_000
15          }
16          return try {
17              val c = connection
18              if (c.responseCode !in 200..299) error("Catalogue request failed: ${c.responseCode}")
19              val root = JSONObject(c.inputStream.bufferedReader().use { it.readText() })
20              val items = root.getJSONArray("items").let { array -> (0 until array.length()).map { parse(array.getJSONObject(it)) } }
21              Page(items, root.optInt("page", page), root.optInt("size", size), root.optInt("total", items.size))
22          } finally { connection.disconnect() }
23      }
